    gamma.sort((left, right) => (String(left) < String(right) ? 1 : String(left) > String(right) ? -1 : 0));
    break;
  }
  case 1: {
    const [chi, ...beta] = [0, gamma.reduce((total, item) => total + item, 0), theta];
