      const theta = /(?<first>[a-z])(b)?/.exec('Lash');
      console.log(theta?.[0] ?? 'none', theta?.index ?? -1, theta?.groups?.first ?? '-', theta === null);
    }
    break;
  }
  default: {
    const iota = new Date(Date.UTC(2024, 0, 10));
    console.log(iota.toISOString(), iota.getUTCDay(), iota.getTime() > 0, iota instanceof Date);
